def run_tool_call(call, registry):
    def result(content, err):
        return {"tool_use_id": call["id"], "content": content, "is_error": err}
    if call["name"] not in registry:
        return result("unknown tool", True)
    func, params = registry[call["name"]]
    args = call.get("input", {})
    if set(args) != set(params) or any(not isinstance(args[k], t) for k, t in params.items()):
        return result("invalid input", True)
    try:
        value = func(**args)
    except Exception:
        return result("tool failed", True)
    return result(str(value), False)

