def run_agent(model, tools, max_steps):
    history = []
    for step in range(1, max_steps + 1):
        action = model(history)
        if action["type"] == "final":
            return {"status": "done", "text": action["text"], "steps": step}
        func = tools.get(action["name"])
        if func is None:
            observation = "error: unknown tool"
        else:
            observation = func(**action["input"])
        history.append((action["name"], observation))
    return {"status": "budget_exceeded", "text": None, "steps": max_steps}

